/** 
 * Upon receiving a private message from a user, deliver that to an instant messaging contact and create one if it does not exist. We can ignore normal chat rooms, since they each have their own ChatRoomListener for managing chat room operations.
 * @param msg the private message
 */
@Override public void onUserPrivMessage(final UserPrivMsg msg){
  final String user=msg.getSource().getNick();
  final String text=Utils.formatMessage(Utils.parse(msg.getText()));
  MessageIrcImpl message=new MessageIrcImpl(text,OperationSetBasicInstantMessaging.HTML_MIME_TYPE,OperationSetBasicInstantMessaging.DEFAULT_MIME_ENCODING,"");
  Contact from=IrcStack.this.provider.getPersistentPresence().findContactByID(user);
  IrcStack.this.provider.getBasicInstantMessaging().fireMessageReceived(message,from);
}
